@push('scripts')<script>
$(function(){const itemModal=bootstrap.Modal.getOrCreateInstance('#itemModal'),printModal=bootstrap.Modal.getOrCreateInstance('#printChoiceModal'),deleteModal=bootstrap.Modal.getOrCreateInstance('#deleteModal');let cart=@json($cart),removeId=null;
function renderCart(data){cart=data;$('#cartCount').text(data.item_count);$('#cartTotal').text(`Rp ${money(data.total)}`);$('#checkoutButton').prop('disabled',!data.item_count);$('#cartItems').html(data.items.length?data.items.map(i=>`<div class="border-bottom py-2"><div class="d-flex justify-content-between"><div><div class="fw-bold">${$('<div>').text(i.name).html()}</div><div class="text-muted">${i.quantity} × Rp ${money(i.price)}</div></div><div class="text-end"><div class="money">Rp ${money(i.subtotal)}</div><button class="btn btn-link text-danger p-0 remove-item" data-id="${i.row_id}">Hapus</button></div></div></div>`).join(''):'<div class="text-center text-muted py-4">Keranjang masih kosong.</div>');updateChange()}
renderCart(cart);$('#productSearch').on('input',function(){const q=this.value.toLowerCase();$('.product-item').each(function(){$(this).toggle($(this).data('search').includes(q))})});$('.product-card').click(function(){const d=$(this).data();$('#itemForm')[0].reset();$('#itemForm [name=product_id]').val(d.id);$('#itemForm [name=quantity]').val(1);$('#itemName').text(d.name);$('#itemStock').text(`Stok ${d.stock} ${d.unit}`);$('#itemPrice').text(`Rp ${money(d.price)}`);clearErrors('#itemForm');itemModal.show()});
$('#itemForm').submit(function(e){e.preventDefault();const b=$('#addItem');buttonLoading(b,true);$.post(@json(route('pos.cart.add')),$(this).serialize()).done(r=>{renderCart(r.data);itemModal.hide();notify(r.message)}).fail(x=>{showErrors('#itemForm',x.responseJSON?.errors);notify(x.responseJSON?.message||'Gagal menambah item.',false)}).always(()=>buttonLoading(b,false))});
$('#cartItems').on('click','.remove-item',function(){removeId=$(this).data('id');const item=cart.items.find(i=>i.row_id===removeId);$('#deleteName').text((item?.name||'item')+' dari keranjang');deleteModal.show()});$('#confirmDelete').click(function(){const b=this;buttonLoading(b,true);$.ajax({url:@json(url('/jual/keranjang'))+'/'+removeId,type:'DELETE'}).done(r=>{renderCart(r.data);deleteModal.hide();notify(r.message)}).fail(x=>notify(x.responseJSON?.message||'Gagal menghapus item.',false)).always(()=>buttonLoading(b,false))});
function updateChange(){const paid=Number($('#paidAmount').val()||0);$('#changeAmount').text(`Rp ${money(Math.max(0,paid-cart.total))}`)}$('#paidAmount').on('input',updateChange);$('#paymentMethod').change(function(){const cash=this.value==='cash';$('#paidField').toggle(cash);if(!cash)$('#paidAmount').val(cart.total);updateChange()});$('#checkoutForm').submit(function(e){e.preventDefault();if(cart.item_count)printModal.show()});$('.checkout-choice').click(function(){const choice=this;$('.checkout-choice').prop('disabled',true);buttonLoading(choice,true);const data=$('#checkoutForm').serializeArray();data.push({name:'print_receipt',value:$(choice).data('print')});$.post(@json(route('pos.checkout')),data).done(r=>{const url=r.data.print_receipt?r.data.show_url+'?receipt=1':r.data.show_url;window.location.assign(url)}).fail(x=>{printModal.hide();showErrors('#checkoutForm',x.responseJSON?.errors);notify(x.responseJSON?.message||'Checkout gagal.',false);$('.checkout-choice').prop('disabled',false);buttonLoading(choice,false)})});});
</script>@endpush
